# ---------------- 落盘：分两批 append 语义（逐批写文件+断言） ----------------
B15 = ["LY-517","LY-518","LY-519","LY-520","LY-521","LY-522","LY-523","LY-524","LY-525","LY-526","LY-527","LY-528","LY-529","LY-530","LY-531","LY-532","LY-533","LY-534","LY-535","LY-536"]
B16 = ["LY-537","LY-538","LY-539","LY-540","LY-541","LY-542","LY-543","LY-601","LY-602","LY-603","LY-604","LY-605","LY-606","LY-607","LY-608","LY-609","LY-610","LY-611","LY-612","LY-613"]

def dump(cid):
    pt, basis, conf, trig = P[cid]
    rec = {"case_id": cid, "prediction_text": pt, "basis": basis, "confidence": conf, "trigger": trig}
    (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")

for cid in B15:
    dump(cid)
assert all((OUT / f"{c}.json").exists() for c in B15), "B15 incomplete"
print("B15 written:", len(B15))
for cid in B16:
    dump(cid)
assert all((OUT / f"{c}.json").exists() for c in B16), "B16 incomplete"
print("B16 written:", len(B16))

# ---------------- 逐件回读自验 ----------------
ids = B15 + B16
cm = ru = di = 0
for cid in ids:
    rec = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
    assert rec["case_id"] == cid
    assert set(rec.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert isinstance(rec["prediction_text"], str) and len(rec["prediction_text"]) > 30, cid
    assert isinstance(rec["basis"], str) and len(rec["basis"]) > 50, cid
    assert 0.0 <= float(rec["confidence"]) <= 1.0, cid
    tr = rec["trigger"]
    assert set(tr.keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
    assert all(isinstance(tr[k], bool) for k in ("changed_main","reserve_used","disputed")), cid
    assert isinstance(tr["reason"], str), cid
    cm += tr["changed_main"]; ru += tr["reserve_used"]; di += tr["disputed"]
print("VERIFIED", len(ids), "changed_main", cm, "reserve_used", ru, "disputed", di)
